import type { Metadata } from "next";
import { SITE } from "@/lib/site";

type SocialInput = {
  /** Card filename under public/og/, generated by `npm run assets:og`. */
  key: string;
  /** Route path, "" for the homepage. Becomes og:url. */
  path: string;
  title: string;
  description: string;
};

export const BUSINESS_ID = `${SITE.url}/#business`;

/**
 * The one LocalBusiness entity, embedded whole wherever a page needs it.
 *
 * Google only resolves an `@id` reference against nodes on the same page, so
 * service pages carry the full node rather than a bare `{ "@id" }` pointer —
 * and every copy stays identical, which is what lets the entity consolidate.
 * Opening hours mirror the table on /contact and the Google Business Profile
 * (Mon–Sat 8–6, Sunday closed); keep all three in step.
 */
export const BUSINESS_SCHEMA = {
  "@type": "HomeAndConstructionBusiness",
  "@id": BUSINESS_ID,
  name: SITE.name,
  legalName: SITE.legalName,
  description: SITE.description,
  url: SITE.url,
  logo: `${SITE.url}/joinery-logo.webp`,
  image: `${SITE.url}/og/home.webp`,
  telephone: SITE.phoneE164,
  email: SITE.email,
  address: {
    "@type": "PostalAddress",
    streetAddress: SITE.address.line1,
    addressLocality: "Al Quoz",
    addressRegion: SITE.address.city,
    addressCountry: "AE",
  },
  areaServed: [
    { "@type": "City", name: "Dubai" },
    { "@type": "Country", name: "United Arab Emirates" },
  ],
  openingHoursSpecification: [
    {
      "@type": "OpeningHoursSpecification",
      dayOfWeek: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
      opens: "08:00",
      closes: "18:00",
    },
  ],
  sameAs: Object.values(SITE.social),
};

/**
 * Open Graph + Twitter metadata for one page.
 *
 * Next merges metadata shallowly: a page that sets no `openGraph` inherits the root
 * layout's whole object — og:url and og:title included — so every page must supply
 * its own. The card URL is relative and resolves against `metadataBase`.
 */
export function socialMeta({ key, path, title, description }: SocialInput): Pick<Metadata, "openGraph" | "twitter"> {
  const image = { url: `/og/${key}.webp`, width: 1200, height: 630, alt: title, type: "image/webp" };
  return {
    openGraph: {
      title,
      description,
      url: `${SITE.url}${path}`,
      siteName: SITE.name,
      type: "website",
      locale: "en_AE",
      images: [image],
    },
    twitter: { card: "summary_large_image", title, description, images: [image] },
  };
}
